"""
Extract failed and fixme-annotated tests from a Playwright JSON report.

The Playwright JSON reporter produces a nested tree of suites, each of which may
contain further suites and a list of specs.  This script walks that tree and
distils it down to two small, stable JSON artifacts that the flaky-test analysis
step (``analyze_e2e_flaky_tests.py``) later aggregates across runs and browsers.

Outputs (written to OUTPUT_DIR):
  failures.json    - {"failures": [...], "metadata": {"browser": str, "has_results": bool, ...}}
  fixme_tests.json - {"fixme_tests": [...]}

Environment variables:
  RESULTS_JSON - Path to the Playwright JSON report (may not exist if the run produced none)
  OUTPUT_DIR   - Directory to write the extracted artifacts into (created if missing)
  BROWSER      - Browser name the report was produced for (e.g. chromium)
  RUN_ID       - Identifier of the CI run the report belongs to
"""

from __future__ import annotations

import json
import os
from pathlib import Path

# Playwright caps error messages at whatever the terminal shows; we keep them short
# so the aggregated Slack message stays well under Block Kit's size limits.
MAX_ERROR_LENGTH = 300


def truncate_error(message: str) -> str:
    """Normalize and truncate a Playwright error message for compact display.

    Strips surrounding whitespace, flattens newlines to spaces and truncates
    anything longer than ``MAX_ERROR_LENGTH`` characters, appending an ellipsis
    (so a truncated message is exactly ``MAX_ERROR_LENGTH + 3`` characters long).
    """
    normalized = message.strip().replace("\r\n", " ").replace("\n", " ").replace("\r", " ")
    if len(normalized) <= MAX_ERROR_LENGTH:
        return normalized
    return normalized[:MAX_ERROR_LENGTH] + "..."


def extract_test_title(spec: dict) -> str:
    """Build a human-readable test title from a Playwright spec dict.

    Uses ``spec['location']['file']`` as the file path (``'unknown'`` if absent)
    and joins the non-empty parts of ``spec['titlePath']`` with ``' > '``.  When
    there are no title parts, only the file path is returned.
    """
    file = spec.get("location", {}).get("file", "unknown")
    parts = [part for part in spec.get("titlePath", []) if part]
    if parts:
        return f"{file}: {' > '.join(parts)}"
    return file


def _extract_error_message(test: dict) -> str:
    """Pull the first available error message out of a test's results."""
    for result in test.get("results", []) or []:
        for err in result.get("errors", []) or []:
            message = err.get("message") if isinstance(err, dict) else err
            if message:
                return truncate_error(str(message))
        error = result.get("error")
        if isinstance(error, dict) and error.get("message"):
            return truncate_error(str(error["message"]))
        if isinstance(error, str) and error:
            return truncate_error(error)
    error = test.get("error")
    if isinstance(error, dict) and error.get("message"):
        return truncate_error(str(error["message"]))
    if isinstance(error, str) and error:
        return truncate_error(error)
    return ""


