    """A test failed if it is marked ``unexpected`` or has a failing result."""
    if test.get("status") in ("unexpected", "failed", "timedOut"):
        return True
    return any(
        (result.get("status") in ("failed", "timedOut")) for result in test.get("results", []) or []
    )


