    """Recursively collect failed/unexpected tests from a list of suites."""
    failures: list = []
    for suite in suites or []:
        for spec in suite.get("specs", []) or []:
            title = extract_test_title(spec)
            spec_file = spec.get("location", {}).get("file", "unknown")
            for test in spec.get("tests", []) or []:
                if _is_failure(test):
                    failures.append(
                        {
                            "test": title,
                            "status": test.get("status", ""),
                            "error": _extract_error_message(test),
                            "spec_file": spec_file,
                        }
                    )
        failures.extend(extract_failures(suite.get("suites", []) or []))
    return failures


