"""
Aggregate extracted E2E results across runs/browsers and format a Slack report.

Consumes the ``failures.json`` / ``fixme_tests.json`` artifacts produced by
``extract_e2e_test_results.py`` (one pair per run per browser), aggregates them
per test, works out which failing tests are flaky enough to be candidates for
being marked as needing a fix, and renders a Slack Block Kit message.

Environment variables (used by ``main``):
  INPUT_DIR         - Directory containing per-run/per-browser artifact subdirectories
  OUTPUT_FILE       - Path to write the rendered Slack message JSON to (optional)
  GITHUB_REPOSITORY - Owner/repo, used in the message header (default apache/airflow)
"""

from __future__ import annotations

import json
import os
from pathlib import Path

SLACK_CHANNEL = "airflow-3-ui"

# A failing test only becomes a "needs fix" candidate once it fails in more than
# this fraction of the (run x browser) data points we have.  A single failure
# across e.g. 10 runs on 3 browsers (~3%) stays below the bar and is ignored.
MIN_FAILURE_RATE = 0.1


def escape_slack_mrkdwn(text: str) -> str:
    """Escape the characters Slack's mrkdwn treats specially.

    ``&`` must be escaped first so the ampersands introduced when escaping
    ``<`` and ``>`` are not themselves re-escaped.
    """
    return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def _failure_count(value: object) -> int:
    """Best-effort count of failures for a single test entry."""
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return value
    if isinstance(value, list):
        return len(value)
    if isinstance(value, dict):
        if "count" in value and isinstance(value["count"], int):
            return value["count"]
        failures = value.get("failures")
        if isinstance(failures, list):
            return len(failures)
        if isinstance(failures, int):
            return failures
    return 0


def identify_flaky_candidates(failures_by_test: dict, runs_with_data: int) -> list:
    """Return failing tests whose failure rate exceeds ``MIN_FAILURE_RATE``.

    ``failures_by_test`` maps a test title to its aggregated failures (a list of
    occurrences, an integer count, or a dict carrying a count).  ``runs_with_data``
    is the number of (run x browser) data points that actually produced results.

    Returns a list of ``{"test", "failure_count", "failure_rate"}`` dicts sorted
    by ``failure_rate`` descending.  Empty input or ``runs_with_data == 0`` yields
    an empty list.
    """
    if not failures_by_test or not runs_with_data:
        return []

    candidates: list = []
    for test, value in failures_by_test.items():
        count = _failure_count(value)
        if count <= 0:
            continue
        failure_rate = count / runs_with_data
        if failure_rate > MIN_FAILURE_RATE:
            candidates.append(
                {
                    "test": test,
                    "failure_count": count,
                    "failure_rate": failure_rate,
                }
            )

    candidates.sort(key=lambda candidate: candidate["failure_rate"], reverse=True)
    return candidates


def _error_text(value: object) -> str:
    """Extract a representative error string from an aggregated test entry."""
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        error = value.get("error") or value.get("message")
        return error if isinstance(error, str) else ""
    if isinstance(value, list):
        for occurrence in value:
            if isinstance(occurrence, dict):
                error = occurrence.get("error") or occurrence.get("message")
                if error:
                    return str(error)
            elif isinstance(occurrence, str) and occurrence:
                return occurrence
    return ""


