        {
            "type": "header",
            "text": {"type": "plain_text", "text": "E2E Flaky Test Report", "emoji": True},
        },
        {
            "type": "section",
            "text": {
                "type": "mrkdwn",
                "text": (
                    f"*Repository:* {escape_slack_mrkdwn(repo)}\n"
                    f"*Runs analyzed:* {len(runs)}\n"
                    f"*Runs with data:* {runs_with_data}"
                ),
            },
        },
        {"type": "divider"},
    ]

    # Failing tests
    if not failures_by_test:
        blocks.append(
            {
                "type": "section",
                "text": {"type": "mrkdwn", "text": ":white_check_mark: No test failures detected."},
            }
        )
    else:
